use std::fs;

use amane::Color;

use super::{config_home, home, write};
use crate::theme::{self, Theme};

// the name kde apps list the scheme under
const NAME: &str = "Amane";

/*
 * a kde color scheme, which kate, dolphin and other kde and qt apps read
 * from kdeglobals; the running ones are told to reload it over d-bus
 */
pub fn export(theme: &Theme) {
    let groups = groups(theme);

    let scheme = format!(
        "# generated by amane, do not edit\n[General]\nColorScheme={NAME}\nName={NAME}\n\n{groups}"
    );

    write(&format!("{}/.local/share/color-schemes/{NAME}.colors", home()), &scheme);

    let path = format!("{}/kdeglobals", config_home());

    let existing = fs::read_to_string(&path).unwrap_or_default();

    write(&path, &patched(&existing, &groups));

    amane::spawn(
        "dbus-send --session --type=signal /KGlobalSettings org.kde.KGlobalSettings.notifyChange int32:0 int32:0 2>/dev/null",
    );
}

// "r,g,b", the way kde writes colors
fn rgb(color: Color) -> String {
    format!("{},{},{}", color.red(), color.green(), color.blue())
}

fn groups(theme: &Theme) -> String {
    let neutral = theme::mix(theme.accent, theme.danger, 0.5);

    let visited = theme::mix(theme.accent, theme.secondary_text, 0.4);

    // what every group shares: the text and decoration colors over its own two backgrounds
    let group = |name: &str, background: Color, alternate: Color, text: Color| {
        let lines = [
            format!("[Colors:{name}]"),
            format!("BackgroundAlternate={}", rgb(alternate)),
            format!("BackgroundNormal={}", rgb(background)),
            format!("DecorationFocus={}", rgb(theme.accent)),
            format!("DecorationHover={}", rgb(theme.accent_hover)),
            format!("ForegroundActive={}", rgb(theme.accent)),
            format!("ForegroundInactive={}", rgb(theme.secondary_text)),
            format!("ForegroundLink={}", rgb(theme.accent)),
            format!("ForegroundNegative={}", rgb(theme.danger)),
            format!("ForegroundNeutral={}", rgb(neutral)),
            format!("ForegroundNormal={}", rgb(text)),
            format!("ForegroundPositive={}", rgb(theme.success)),
            format!("ForegroundVisited={}", rgb(visited)),
        ];

        lines.join("\n") + "\n\n"
    };

    let mut text = String::new();

    text.push_str(&group("View", theme.background, theme.surface, theme.text));
    text.push_str(&group("Window", theme.surface, theme.background, theme.text));
    text.push_str(&group("Button", theme.selected_surface, theme.hover_surface, theme.text));
    text.push_str(&group("Selection", theme.accent, theme.accent_hover, theme.on_accent));
    text.push_str(&group("Tooltip", theme.surface, theme.background, theme.text));
    text.push_str(&group("Complementary", theme.background, theme.surface, theme.text));
    text.push_str(&group("Header", theme.surface, theme.background, theme.text));

    text.push_str(&format!(
        "[WM]\nactiveBackground={}\nactiveForeground={}\ninactiveBackground={}\ninactiveForeground={}\n",
        rgb(theme.surface),
        rgb(theme.text),
        rgb(theme.background),
        rgb(theme.secondary_text),
    ));

    text
}

/*
 * kdeglobals with every color group swapped for the new ones and the
 * scheme's name set; every other group and key in it is kept
 */
fn patched(existing: &str, groups: &str) -> String {
    let mut kept = String::new();

    let mut skipping = false;
    let mut in_general = false;
    let mut named = false;

    for line in existing.lines() {
        let trimmed = line.trim();

        if trimmed.starts_with('[') {
            skipping = trimmed.starts_with("[Colors:") || trimmed.starts_with("[ColorEffects:") || trimmed == "[WM]";

            in_general = trimmed == "[General]";

            if skipping {
                continue;
            }
        }

        if skipping {
            continue;
        }

        if in_general && trimmed.starts_with("ColorScheme=") {
            kept.push_str(&format!("ColorScheme={NAME}\n"));

            named = true;

            continue;
        }

        kept.push_str(line);
        kept.push('\n');

        if trimmed == "[General]" && !existing.contains("ColorScheme=") {
            kept.push_str(&format!("ColorScheme={NAME}\n"));

            named = true;
        }
    }

    if !named {
        kept.push_str(&format!("\n[General]\nColorScheme={NAME}\n"));
    }

    format!("{}\n\n{groups}", kept.trim_end())
}
